    row.p2Isa = row.p2CashIsa + row.p2SsIsa + row.p2Lisa;
    row.p1Total = row.p1Pension + row.p1Isa + row.p1OtherSavings;
    row.p2Total = row.p2Pension + row.p2Isa + row.p2OtherSavings;
    row.totalPension = row.p1Pension + row.p2Pension;
    row.incomeTax = row.p1Tax + row.p2Tax;          // household, from rounded parts (same pattern as totalPension)
