// Living Standard level for a today's-money income (intent 037). The bands
// are today's-money figures, so the income compared with them must be too.
function livingStandardLevel(incomeToday, isCouple) {
  const b = isCouple ? UK_REFERENCE.plsa.couple : UK_REFERENCE.plsa.single;
  if (incomeToday >= b.comfortable) return 'Comfortable';
  if (incomeToday >= b.moderate) return 'Moderate';
  if (incomeToday >= b.minimum) return 'Minimum';
  return 'Below Minimum';
}
// Household figures for the first year everyone is retired ("bothYear"),
// shared by the summary cards, the What if / What matters most panels, the
