    totalPot: row.totalPension + row.totalIsa + row.totalOtherSavings,
    pensionIncome,
    savingsIncome,
    statePension,
    dbPension,
    grossIncome,
    incomeTax,
    annualIncome: grossIncome - incomeTax,
    year: bothYear,
    perPerson: parts
