    for (let y = 0; y < years; y++) returnShocks.push({ growth: normal() * o.growthVolatility, cash: normal() * o.cashVolatility });
    const rows = projectJoint({ ...args, returnShocks });
    if (planSucceeds(rows, base.firstRet, base.planEnd)) successes++;
